                except ProcessLookupError:
                    pass

        def handle_signal(signum: int, _frame: Any) -> None:
            terminate_child_group(signal.SIGTERM)
            try:
                child.wait(timeout=PROCESS_GROUP_TERMINATION_GRACE_SECONDS)
            except subprocess.TimeoutExpired:
                pass
